"""Absichtlich eingebaute Fehler für die Selbstabnahme der Prüfmaschine V1.2 (nur in einer frisch entpackten KOPIE).

Jede Mutation ersetzt genau EINE Stelle. Passt die Stelle nicht genau einmal, ist die Mutation nicht ausgeführt
(BLOCKIERT) - eine Mutation, die nicht greift, gilt nie als erkannt.
'erwartet' ist VOR dem Lauf festgelegt (aus dem Vertrag abgeleitet, nicht aus Messungen): JEDER genannte
(Fall, Glied)-Punkt muss im unveränderten Lauf genau GRÜN und im mutierten Lauf genau ROT sein.
"""
from __future__ import annotations

from pathlib import Path

MUTATIONEN = {
    'M1_falsche_figuren_id': {'datei': 'matrix_api/app.py', 'alt': 'out = kernel.commit_puppet(session, speaker, _pin.get("speech") or "", _pin.get("legacyAction"), plan=_pplan,', 'neu': 'out = kernel.commit_puppet(session, next((n for n in natives if str(n.get("id")) != str(speaker.get("id")) and str(n.get("id")) in [str(x) for x in ((session.get("scene") or {}).get("presentIds") or [])]), speaker), _pin.get("speech") or "", _pin.get("legacyAction"), plan=_pplan,  # KP-MUTATION M1', 'erwartet': [('PU1_handlung_eigenes_subjekt', 9), ('PU2_anrede_gegen_ui_auswahl', 9)], 'beschreibung': 'Der Puppet-Writer schreibt die Eingabe einer ANDEREN anwesenden Figur zu.'},
    'M2_falscher_adressat': {'datei': 'matrix_api/app.py', 'alt': 'target_id=(_pin.get("speechTarget") if _pin.get("speechTargetSet") else _ptarget_id),', 'neu': 'target_id=next((str(n.get("id")) for n in natives if str(n.get("id")) not in (str(speaker.get("id")), str(_pin.get("speechTarget") if _pin.get("speechTargetSet") else _ptarget_id)) and str(n.get("id")) in [str(x) for x in ((session.get("scene") or {}).get("presentIds") or [])]), None),  # KP-MUTATION M2', 'erwartet': [('PU2_anrede_gegen_ui_auswahl', 9)], 'beschreibung': 'Der Writer bindet die Rede an einen FALSCHEN Adressaten (eine andere anwesende Figur statt des gebundenen).'},
    'M3_fehlender_commit': {'datei': 'matrix_api/app.py', 'alt': 'saved = kernel_session_response(conn, aid or out.get("userId") or "admin", out)\n                matrix_live_log.live_log("SQLITE_COMMIT", trace_id=trace_id, status="PASS", session_id=saved.get("id"))\n                return {"ok": True, "session": saved, "trace_id": trace_id, "presenceAdded": out.get("puppetPresenceAdded")}', 'neu': 'saved = dict(session)  # KP-MUTATION M3: nichts gespeichert, trotzdem Erfolg\n                matrix_live_log.live_log("SQLITE_COMMIT", trace_id=trace_id, status="PASS", session_id=saved.get("id"))\n                return {"ok": True, "session": saved, "trace_id": trace_id, "presenceAdded": out.get("puppetPresenceAdded")}', 'erwartet': [('PU1_handlung_eigenes_subjekt', 6), ('PU1_handlung_eigenes_subjekt', 9), ('PU1_handlung_eigenes_subjekt', 13), ('PU2_anrede_gegen_ui_auswahl', 6), ('PU2_anrede_gegen_ui_auswahl', 9), ('PU2_anrede_gegen_ui_auswahl', 13)], 'beschreibung': 'Die Puppet-Route meldet Erfolg, schreibt aber nichts nach SQLite.'},
    'M4_nebenwirkung_stamm': {'datei': 'matrix_api/app.py', 'alt': '                    fact_type="puppet",\n                    commit_status="pending_sqlite",\n                )\n                last = "WRITER"\n                saved = kernel_session_response(conn, aid or out.get("userId") or "admin", out)', 'neu': '                    fact_type="puppet",\n                    commit_status="pending_sqlite",\n                )\n                last = "WRITER"\n                conn.execute("UPDATE characters SET json=json_set(json, \'$.kpMutation\', lower(hex(randomblob(4)))) WHERE id=?", (str(speaker.get("id")),))  # KP-MUTATION M4\n                saved = kernel_session_response(conn, aid or out.get("userId") or "admin", out)', 'erwartet': [('PU1_handlung_eigenes_subjekt', 18), ('PU2_anrede_gegen_ui_auswahl', 18)], 'beschreibung': 'Der Puppet-Writer verändert bei JEDEM Aufruf nebenbei den Figurenstamm (unerlaubte Nebenwirkung).'},
    'M5_abwesende_als_zeugen': {'datei': 'matrix_api/kernel.py', 'alt': '        candidates = ids if ids is not None else present\n        out = []\n        for cid in candidates:\n            if cid not in present:\n                continue\n            rt = runtimes.get(cid) or {}\n            if place and rt.get("position") and rt.get("position") != place:\n                continue\n', 'neu': '        candidates = list(dict.fromkeys(list(ids if ids is not None else present) + list(runtimes)))  # KP-MUTATION M5\n        out = []\n        for cid in candidates:\n            rt = runtimes.get(cid) or {}\n', 'erwartet': [('PU1_handlung_eigenes_subjekt', 10), ('PU2_anrede_gegen_ui_auswahl', 10)], 'beschreibung': 'Die Szenenwahrnehmung prüft Anwesenheit und Ort nicht mehr: abwesende Figuren hören und sehen mit.'},
    'M6_kein_zeugenwissen': {'datei': 'matrix_api/kernel.py', 'alt': 'def _record_fact_witnesses(session: dict, truth: dict, facts: list[dict], turn: int) -> None:\n    for fact in facts:\n', 'neu': 'def _record_fact_witnesses(session: dict, truth: dict, facts: list[dict], turn: int) -> None:\n    return  # KP-MUTATION M6: kein kanonisches Zeugenwissen\n    for fact in facts:\n', 'erwartet': [('PU1_handlung_eigenes_subjekt', 10), ('PU1_handlung_eigenes_subjekt', 13), ('PU2_anrede_gegen_ui_auswahl', 10), ('PU2_anrede_gegen_ui_auswahl', 13)], 'beschreibung': 'Der Writer legt für Zeugen kein Zeugenwissen (WitnessKnowledge) mehr an.'},
    'M7_avatar_falsches_ziel': {'datei': 'matrix_api/app.py', 'alt': '                                raise WriterError("session advanced while preparing input", 409, "STALE_SESSION")\n                            session = kernel.commit_turn(\n                                locked, truth=incoming, speaker=speaker, present=knatives,\n', 'neu': '                                raise WriterError("session advanced while preparing input", 409, "STALE_SESSION")\n                            session = kernel.commit_turn(\n                                locked, truth={**incoming, "target_id": next((str(c.get("id")) for c in knatives if isinstance(c, dict) and str(c.get("id")) not in (str(incoming.get("target_id")), str(incoming.get("input_actor_id")))), None)}, speaker=speaker, present=knatives,  # KP-MUTATION M7\n', 'erwartet': [('AV1_frage_und_antwort', 9)], 'beschreibung': 'Die Avatar-Eingabe wird mit einem falschen Adressaten (andere anwesende Figur) gespeichert.'},
    'M8_god_koerper_falsche_figur': {'datei': 'matrix_api/kernel.py', 'alt': '        _w = write_body_change(s, str(target_id), _gchg, fact_id=fact["id"], turn=turn, authority="god", text=text,', 'neu': '        _w = write_body_change(s, next((str(x) for x in ((s.get("scene") or {}).get("presentIds") or []) if str(x) != str(target_id)), str(target_id)), _gchg, fact_id=fact["id"], turn=turn, authority="god", text=text,  # KP-MUTATION M8', 'erwartet': [('GO1_bewusstlos', 11)], 'beschreibung': 'Die von God gesetzte Körperänderung landet bei einer anderen anwesenden Figur.'},
    'M9_regie_fail_open': {'datei': 'matrix_api/app.py', 'alt': '                if not has_effect and not legacy_executed:\n                    # Der vorhandene Binder hat den fehlenden Akteur bereits\n', 'neu': '                if False and not has_effect and not legacy_executed:  # KP-MUTATION M9: Regie ohne gebundene Wirkung gilt als Erfolg\n                    # Der vorhandene Binder hat den fehlenden Akteur bereits\n', 'erwartet': [('RE2_unbekannte_figur', 5), ('RE2_unbekannte_figur', 6)], 'beschreibung': 'Regie ohne gebundenen Akteur und ohne Wirkung wird nicht mehr abgelehnt (fail-open).'},
}


def anwenden(root: Path, name: str) -> str:
    m = MUTATIONEN[name]
    p = root / m["datei"]
    text = p.read_text(encoding="utf-8")
    n = text.count(m["alt"])
    if n != 1:
        raise RuntimeError("Mutation %s: Stelle %d-mal gefunden (erwartet genau 1)" % (name, n))
    p.write_text(text.replace(m["alt"], m["neu"]), encoding="utf-8")
    return "angewendet: %s (%s)" % (name, m["beschreibung"])
